import{at as e,it as t,t as n,yt as r}from"./chunks/framework.ILid7KTz.js";var i=JSON.parse(`{"title":"Using The Response","description":"","frontmatter":{},"headers":[],"relativePath":"guides/the-manual/requests/using-the-response.md","filePath":"guides/the-manual/requests/using-the-response.md"}`),a={name:`guides/the-manual/requests/using-the-response.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="using-the-response" tabindex="-1">Using The Response <a class="header-anchor" href="#using-the-response" aria-label="Permalink to “Using The Response”">​</a></h1><p><a href="/pr-preview/pr-11087/api/@warp-drive/core/classes/Store#request">Requests</a> return a subclass of <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Promise" target="_blank" rel="noreferrer">Promise</a> we call a <a href="/pr-preview/pr-11087/api/@warp-drive/core/request/types/Future">Future</a>.</p><h3 id="special-powers" tabindex="-1">Special Powers <a class="header-anchor" href="#special-powers" aria-label="Permalink to “Special Powers”">​</a></h3><p>Futures expose a number of crucial features for working with requests.</p><ul><li><a href="/pr-preview/pr-11087/api/@warp-drive/core/request/types/Future#lid">lid</a> which gives access to the identity of the request</li><li><a href="/pr-preview/pr-11087/api/@warp-drive/core/request/types/Future#getstream">getStream()</a> which will resolve to the response stream once it is available</li><li><a href="/pr-preview/pr-11087/api/@warp-drive/core/request/types/Future#abort">abort()</a> which will attempt to abort the request.</li></ul><h3 id="return-values" tabindex="-1">Return Values <a class="header-anchor" href="#return-values" aria-label="Permalink to “Return Values”">​</a></h3><p>Futures both resolve and reject with an object (<a href="/pr-preview/pr-11087/api/@warp-drive/core/types/request/types/StructuredDocument">{ request, response, content }</a>) representing the original <a href="/pr-preview/pr-11087/api/@warp-drive/core/types/request/types/RequestInfo">RequestInfo</a>, the <a href="https://developer.mozilla.org/en-US/docs/Web/API/Response" target="_blank" rel="noreferrer">Response</a> set by the handler chain (if any), and the <a href="#content">processed content</a>.</p><h3 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to “Errors”">​</a></h3><p>If the <code>Future</code> rejects, it throws either an <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Error" target="_blank" rel="noreferrer">Error</a> an <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/AggregateError" target="_blank" rel="noreferrer">AggregateError</a> or a <a href="https://developer.mozilla.org/en-US/docs/Web/API/DOMException" target="_blank" rel="noreferrer">DOMException</a> that maintains the <code>{ request, response, content }</code> shape but is also an Error instance itself.</p><p>If using the error originates from the <a href="/pr-preview/pr-11087/api/@warp-drive/core/variables/Fetch">Fetch Handler</a> the error will be a <a href="/pr-preview/pr-11087/api/@warp-drive/core/types/request/types/FetchError">FetchError</a></p><h2 id="consuming-the-response" tabindex="-1">Consuming The Response <a class="header-anchor" href="#consuming-the-response" aria-label="Permalink to “Consuming The Response”">​</a></h2><p>On their own, <code>Futures</code> may appear to have an overly verbose return shape and the value of the features they enhance promises with may not be immediately clear. But this is because in the general case it is expected that you <strong>won&#39;t</strong> resolve the future yourself with <code>await</code>, but instead will pass it around your app as a value.</p><p>Maintaining access to the <code>Future&#39;s</code> reference allows you to use it with declarative reactive paradigms using utilities such as <code>getRequestState</code> or components like <code>&lt;Request /&gt;</code>.</p><p>We call this <code>Reactive Control Flow</code>, you may want to <a href="https://youtu.be/HQiKFaTAahM?si=Ng8lCpSQkwrHzGd5&amp;t=312" target="_blank" rel="noreferrer">watch the talk where we introduced this feature</a>.</p><h2 id="content" tabindex="-1">Response Content <a class="header-anchor" href="#content" aria-label="Permalink to “Response Content”">​</a></h2><p>The <code>content</code> property contains whatever the <a href="/pr-preview/pr-11087/api/@warp-drive/core/classes/RequestManager#use">request handler pipeline</a> resolves with. For requests that do not use the cache, this will be whatever the last handler to process the response returns.</p><p>For requests that do use the cache (most requests), the content property will be a <a href="/pr-preview/pr-11087/api/@warp-drive/core/reactive/types/ReactiveDocument">ReactiveDocument</a>.</p><div class="tip custom-block"><p class="custom-block-title">💡 TIP</p><p>Whether a request uses the cache (or doesn&#39;t) <strong>is not</strong> governed by whether the request is cacheable (has a <a href="/pr-preview/pr-11087/api/@warp-drive/core/types/identifier/types/RequestKey">RequestKey</a>) but by whether the request should interact with the Cache. See the <a href="./../caching/#determining-if-a-request-can-use-the-cache">caching guide</a> for more info.</p></div>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};